/* 服务方案交互原型：仅使用当前浏览器的演示记录，不连接业务接口。 */
'use strict';
const $ = (selector) => document.querySelector(selector);
const storageKey = 'blisstribe-service-prototype-v1';
const icons = {
  leaf:'M5 19C3 8 9 3 20 4c0 11-6 16-15 15Zm0 0L16 8',
  grid:'M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z',
  calendar:'M5 5h14v15H5zM8 3v4M16 3v4M5 10h14M8 14h2M14 14h2',
  heart:'M12 20S3 14 3 8a5 5 0 0 1 9-3 5 5 0 0 1 9 3c0 6-9 12-9 12Z',
  file:'M6 3h8l4 4v14H6zM14 3v5h4M9 12h6M9 16h6',
  user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2',
  arrow:'m9 5 7 7-7 7', back:'m15 5-7 7 7 7', check:'m5 12 4 4L19 6',
  clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 7v5l3 2',
  bag:'M5 7h14l1 14H4L5 7ZM8 7V6a4 4 0 0 1 8 0v1',
  help:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM9 8a3 3 0 0 1 6 1c0 2-3 2-3 4M12 17h.01',
  refresh:'M20 7v5h-5M4 17v-5h5M20 12a8 8 0 0 0-14-5M4 12a8 8 0 0 0 14 5',
  wallet:'M3 6h18v15H3zM3 6V4h15v2M16 12h5v5h-5z',
  alert:'m12 3 10 18H2L12 3ZM12 9v5M12 17h.01',
};
const icon = (name) => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name] || icons.file}"/></svg>`;
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = (fen) => `¥${(fen / 100).toFixed(2)}`;
const offers = {
  assessment:{name:'初次服务评估',subtitle:'了解需求，确认适合的服务安排',price:6000,count:1,unit:6000,goods:0,cost:4000,rate:0,label:'一次评估'},
  single:{name:'单次专业服务',subtitle:'机构确认项目后，按次预约',price:10000,count:1,unit:10000,goods:0,cost:6000,rate:0.1,label:'一次服务'},
  package:{name:'阶段服务方案',subtitle:'十次服务 · 一份配套护理用品',price:100000,count:10,unit:9000,goods:10000,cost:6000,rate:0.1,label:'十次服务 + 配套商品'},
};
const initial = () => ({version:1,qualified:false,consultation:null,experience:null,orders:[],activeId:null,scenario:'start',events:[]});
let state;
try { const saved = JSON.parse(localStorage.getItem(storageKey)); state = saved?.version === 1 ? saved : initial(); } catch { state = initial(); }
let role = 'patient', page = 'product', operatorTab = 'appointments', filter = 'all', offerId = 'package', uiState = 'normal';
let selectedDay = 0, selectedTime = '09:30', bookingKind = 'service';
let toastTimer;
const current = () => state.orders.find(o => o.id === state.activeId);
const latestRefund = (o=current()) => o?.refunds.at(-1);
const pendingRefund = (o=current()) => o?.refunds.find(r => ['pending','processing','failed'].includes(r.status));
const refundedCount = (o) => o.refunds.filter(r=>r.status==='success').reduce((sum,r)=>sum+r.count,0);
const goodsRefunded = (o) => o.refunds.some(r=>r.status==='success' && r.goods);
const remaining = (o=current()) => o ? offers[o.offer].count - o.used - refundedCount(o) : 0;
const available = (o=current()) => Math.max(0, remaining(o) - (pendingRefund(o)?.count || 0) - (['pending','confirmed','arrived'].includes(o?.appointment?.status) ? 1 : 0));
const offer = () => offers[current()?.offer || offerId];
const time = () => new Date().toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});
const dates = () => [2,3,4].map(offset=>{const d=new Date();d.setDate(d.getDate()+offset);return {short:`${d.getMonth()+1}月${d.getDate()}日`,label:['周日','周一','周二','周三','周四','周五','周六'][d.getDay()],date:d.toISOString()};});
function save(){try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{toast('浏览器未允许保存，本次演示仍可继续');}}
function log(message){state.events.unshift({time:time(),message});state.events=state.events.slice(0,20);save();}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function button(text,action,kind='',attrs=''){return `<button class="btn ${kind}" data-action="${action}" ${attrs}>${text}</button>`;}
function tag(text,kind=''){return `<span class="tag ${kind}">${text}</span>`;}
function note(text,kind=''){return `<div class="notice ${kind}">${text}</div>`;}
function empty(title,desc,action,label){return `<div class="empty">${icon('file')}<h3>${title}</h3><p>${desc}</p>${action?button(label,action,'primary'):''}</div>`;}
const titleMap={product:'服务介绍',consult:'咨询了解',consultation:'咨询进度',offering:'方案详情',checkout:'确认购买',success:'购买成功',services:'我的服务',plan:'服务计划',booking:'预约服务',appointment:'预约详情',records:'服务记录',refund:'申请退款',refundDetail:'退款详情',goods:'配套商品'};
function go(target){page=target;uiState='normal';render();}
function makeOrder(id=offerId){const o={id:`SV-${String(Date.now()).slice(-8)}-${state.orders.length+1}`,offer:id,paidAt:time(),used:0,appointment:null,records:[],refunds:[],goodsDelivered:false,dispute:false};state.orders.push(o);state.activeId=o.id;return o;}
function appointment(kind='service'){return {kind,date:dates()[selectedDay].short,time:selectedTime,status:'pending',staff:'陈医生',nurse:'李护士'};}
function seed(scene){
  state=initial();state.scenario=scene;filter='all';offerId='package';bookingKind='service';selectedDay=0;selectedTime='09:30';
  if(scene!=='start')state.qualified=true;
  if(['paid','booked','completed','refund'].includes(scene)){
    const o=makeOrder('package');
    if(scene==='booked'){o.appointment=appointment();}
    if(['completed','refund'].includes(scene)){o.used=3;o.goodsDelivered=true;o.records=[1,2,3].map(n=>({id:n,date:`第 ${n} 次服务`,staff:'陈医生',nurse:'李护士',registered:time()}));}
    if(scene==='refund')o.refunds.push({count:7,goods:false,amount:63000,status:'pending',reason:'调整服务安排',createdAt:time()});
  }
  uiState=scene==='unavailable'?'unavailable':'normal';page=scene==='start'||scene==='ready'||scene==='unavailable'?'product':scene==='refund'?'refundDetail':'plan';operatorTab=scene==='refund'?'refunds':scene==='start'||scene==='ready'?'intake':'appointments';
  log('载入演示场景');render();
}
function dialog(title,content,actions){$('#dialog').innerHTML=`<div class="row between"><h2 id="dialog-title">${title}</h2><button class="btn sm" data-action="close-dialog" aria-label="关闭弹窗">×</button></div><div class="dialog-content">${content}</div><div class="dialog-actions">${actions}</div>`;$('#dialog').showModal();}
function closeDialog(){$('#dialog').close();}
function refundStatus(r){return {pending:'退款待审核',processing:'渠道处理中',success:'退款成功',rejected:'退款未通过',withdrawn:'申请已撤回',failed:'退款异常'}[r?.status]||'暂无退款';}
function appStatus(a){return {pending:'待机构确认',confirmed:'预约已确认',arrived:'已到场',completed:'服务已完成',cancelled:'预约已取消'}[a?.status]||'尚未预约';}
function group(o){if(pendingRefund(o)&&available(o)===0)return 'after';if(remaining(o)>0||offers[o.offer].goods&&!o.goodsDelivered&&!goodsRefunded(o))return 'active';if(o.refunds.some(r=>r.status==='success'))return 'closed';return 'done';}
function orderSummary(o=current()) {if(!o)return '';const f=offers[o.offer];return `<div class="row"><div class="program-mini">${icon(o.offer==='assessment'?'heart':'leaf')}</div><div><h3>${f.name}</h3><p class="muted">${f.label}</p></div></div>`;}
function shell(){
 const patient=role==='patient';
 return `<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">${icon('leaf')}</span>心悦部落</div><div class="brand-sub">让服务有序发生</div><div class="nav-caption">交互原型 · 需求 V1.2</div>
 ${[['product','leaf','服务产品'],['services','heart','我的服务'],['consultation','file','咨询进度']].map(([target,i,t])=>`<button class="side-link ${patient&&page===target?'active':''}" data-action="patient-page" data-page="${target}">${icon(i)}${t}</button>`).join('')}
 <div class="divider"></div><button class="side-link ${role==='operator'?'active':''}" data-action="role" data-role="operator">${icon('grid')}机构运营工作台</button><button class="side-link ${role==='guide'?'active':''}" data-action="role" data-role="guide">${icon('help')}原型阅读指引</button>
 <div class="side-bottom"><span class="review-label">交互评审版 / 01</span><p>使用虚构数据体验完整流程。角色切换共享当前演示记录。</p><button class="link" data-action="reset">${icon('refresh')}重置演示</button></div></aside>
 <main class="main"><header class="topbar"><span class="topbar-title">产品设计 <span style="margin:0 9px;color:#abb5aa">/</span> 服务方案与履约</span><span class="demo-badge">演示数据 · 不产生交易</span><div class="role-switch" aria-label="切换角色">${[['patient','患者端'],['operator','机构运营']].map(([r,t])=>`<button class="${role===r?'active':''}" data-action="role" data-role="${r}" aria-pressed="${role===r}">${t}</button>`).join('')}</div><div class="avatar">${patient?'患':'运'}</div></header>
 <section class="workspace">${role==='guide'?guide():patient?patientWorkspace():operatorWorkspace()}</section></main></div>`;
}
function patientWorkspace(){return `<div class="intro"><div><div class="eyebrow">PATIENT EXPERIENCE</div><h1>每一步，都清楚可见。</h1><p>从了解服务到完成预约，让患者知道下一步该做什么。</p></div>${tag('患者端 · 小程序')}</div><div class="preview-grid"><div class="device-zone"><div class="device"><div class="statusbar"><span>9:41</span><span>▮▮▮ &nbsp; Wi-Fi &nbsp; ▰</span></div><div class="mobile-nav"><button data-action="back" aria-label="返回">${icon('back')}</button><strong>${titleMap[page]||'我的服务'}</strong><span class="wx-capsule">··· ⊙</span></div><div class="phone-body" id="phone-body">${patientContent()}</div>${['normal','unavailable'].includes(uiState)?footer():''}<nav class="mobile-tabs" aria-label="小程序导航">${[['product','leaf','服务'],['services','heart','我的服务'],['consultation','file','咨询']].map(([p,i,t])=>`<button data-action="nav" data-page="${p}" class="${page===p?'active':''}">${icon(i)}${t}</button>`).join('')}</nav></div></div><aside class="aside">${reviewCards()}</aside></div>`;}
function reviewCards(){const o=current();return `<div class="card"><div class="eyebrow">当前交互</div><h3>${titleMap[page]||'患者页面'}</h3><p>${({product:'浏览后咨询或预约评估；符合条件的患者可直接查看方案。',checkout:'逐项确认费用与购买规则，再模拟付款。',plan:'可用次数、已预约和售后冻结分别呈现，下一步行动放在最前。',booking:'申请占用次数，机构确认后才视为预约成功。',refund:'合并取消预约与退款申请，仅冻结所选的未使用内容。',refundDetail:'运营审核与渠道退款成功分开展示。',appointment:'切换机构运营即可处理当前预约，再切回查看变化。'})[page]||'点击页面按钮继续。切换上方角色可以接着处理同一笔业务。'}</p></div>
 <div class="card"><h3>快速载入场景</h3><div class="scenarios">${[['start','01','首次咨询'],['ready','02','已评估，可购买'],['paid','03','已购买，待预约'],['booked','04','预约待确认'],['completed','05','已完成三次服务'],['refund','06','剩余七次退款'],['unavailable','07','暂无可约时段']].map(([s,n,t])=>`<button class="scenario ${state.scenario===s?'active':''}" data-action="scenario" data-scene="${s}"><span>${n} &nbsp; ${t}</span>${icon('arrow')}</button>`).join('')}</div><small>载入场景会替换当前浏览器中的演示进度。</small><div class="row between"><button class="link" data-action="role" data-role="guide">阅读指引</button><button class="link" data-action="reset">重置演示</button></div></div>
 <div class="card"><h3>当前业务记录</h3><div class="scene-status"><div class="row"><span class="muted">评估资格</span>${tag(state.qualified?'允许购买':'尚未评估',state.qualified?'':'gray')}</div><div class="row"><span class="muted">当前订单</span><span>${o?offers[o.offer].name:'暂无'}</span></div><div class="row"><span class="muted">可用 / 已完成</span><strong>${available(o)} / ${o?.used||0}</strong></div></div><div class="divider"></div><div class="demo-tools"><label for="view-state">页面状态</label><select id="view-state" data-control="view-state"><option value="normal" ${uiState==='normal'?'selected':''}>正常</option><option value="loading" ${uiState==='loading'?'selected':''}>加载中</option><option value="error" ${uiState==='error'?'selected':''}>加载失败</option></select></div></div>`;}
function patientContent(){if(uiState==='loading')return `<div class="stack">${note('正在加载服务信息…')}<div class="skeleton"></div><div class="skeleton" style="height:170px"></div><div class="skeleton"></div></div>`;if(uiState==='error')return empty('暂时没有加载成功','请检查网络后重试，已有服务不会丢失。','retry','重新加载');return ({product:productPage,consult:consultPage,consultation:consultationPage,offering:offeringPage,checkout:checkoutPage,success:successPage,services:servicesPage,plan:planPage,booking:bookingPage,appointment:appointmentPage,records:recordsPage,refund:refundPage,refundDetail:refundDetailPage,goods:goodsPage}[page]||productPage)();}
function productPage(){return `<div class="hero"><svg class="illustration" viewBox="0 0 200 180" aria-hidden="true"><circle cx="125" cy="85" r="68" fill="#dce8c9"/><path d="M99 169C75 125 115 88 117 38" stroke="#799766" stroke-width="2" fill="none"/><ellipse cx="104" cy="66" rx="20" ry="37" transform="rotate(-40 104 66)" fill="#91aa75"/><ellipse cx="136" cy="102" rx="24" ry="42" transform="rotate(45 136 102)" fill="#b0c492"/><ellipse cx="87" cy="123" rx="21" ry="32" transform="rotate(-38 87 123)" fill="#718f61"/></svg><div class="content"><div class="eyebrow">心悦 · 机构服务</div><h2>把每一次服务，<br>安排得刚刚好。</h2><p>先了解需求，再由机构确认适合您的服务与预约安排。</p>${tag('机构评估后购买')}</div><div class="hero-bottom"><span>单次 / 阶段方案</span><span>线下服务</span><span>全程进度可查</span></div></div><div class="stack">
 <div class="card"><div class="row between"><div><h3>心悦服务中心</h3><small>演示机构 · 接待时间 09:00–18:00</small></div>${icon('arrow')}</div><div class="divider"></div><div class="inline-info">${icon('calendar')}${state.scenario==='unavailable'?'暂无可约时段，可先咨询':`近期可约：${dates()[0].short} 起`}</div></div>
 <div class="section-heading"><h3>选择适合您的开始</h3><button class="link" data-action="nav" data-page="consult">咨询了解 ${icon('arrow')}</button></div>
 <button class="card" style="text-align:left" data-action="free-experience" aria-label="领取初次免费体验"><div class="row between"><h3>初次体验</h3><strong style="color:var(--green)">免费</strong></div><p class="muted" style="margin:7px 0">一次体验名额，由机构确认时间及服务安排</p><small>每人限领取一次 · 名额有效期 30 天</small></button>
 ${Object.entries(offers).map(([id,f])=>`<button class="card" style="text-align:left" data-action="offer" data-offer="${id}" aria-label="查看${f.name}"><div class="row between"><h3>${f.name}</h3>${id==='package'?tag('连续服务'):''}</div><p class="muted" style="margin:7px 0">${f.subtitle}</p><div class="row between"><strong class="amount">${money(f.price)}</strong>${icon('arrow')}</div></button>`).join('')}
 <div class="card"><h3>您会经历的服务流程</h3><div class="divider"></div><ol class="step-list"><li class="done">了解与评估<small>机构确认服务适用性</small></li><li>选择方案并预约<small>确认时间后再到场</small></li><li>执行与跟进<small>每次服务都有可查看的记录</small></li></ol></div>${note('具体服务安排由机构和医生确认。购买方案不替代专业评估。')}</div>`;}
function consultPage(){return `<form id="consult-form" data-form="consult" class="stack"><div class="card"><h3>说说您想了解的内容</h3><p class="muted" style="margin-top:8px">机构人员将根据您的需求协助安排。</p><div class="divider"></div><div class="stack"><label class="field">称呼<input name="name" required maxlength="20" value="体验用户" autocomplete="off"></label><label class="field">咨询内容<textarea name="message" required maxlength="200" placeholder="如：想先体验，了解后续服务安排">想了解阶段服务方案，先预约一次体验。</textarea></label><label class="check"><input type="checkbox" required name="consent">同意机构联系并跟进本次咨询</label></div></div>${note('演示无需真实手机号，也不会发送消息给任何人。')}<button class="btn primary full" type="submit">提交咨询</button></form>`;}
function consultationPage(){return `<div class="stack">${!state.consultation&&!state.experience&&!state.qualified?empty('还没有咨询记录','先说说您的需求，由机构协助安排。','start-consult','咨询了解'):`<div class="card"><div class="row between"><h3>机构服务咨询</h3>${tag(state.qualified?'可购买方案':'跟进中',state.qualified?'':'warn')}</div><div class="divider"></div><ol class="step-list"><li class="done">咨询已提交<small>${esc(state.consultation?.message||'初次体验与服务安排')}</small></li><li class="${state.experience?'done':''}">体验与评估<small>${state.experience?`${esc(state.experience.date)} ${esc(state.experience.time)} · ${appStatus(state.experience)}`:'机构将协助确认体验时间'}</small></li><li class="${state.qualified?'done':''}">可购买确认<small>${state.qualified?'陈医生确认 · 当前机构 · 阶段及单次服务 · 有效 30 天':'完成机构评估后查看可购买方案'}</small></li></ol></div><div class="card"><h3>${state.qualified?'下一步，选择服务方案':'下一步，预约初次体验'}</h3><p class="muted" style="margin:9px 0">${state.qualified?'购买前可逐项查看价格与退款规则。':'体验时间由机构确认，不代表已经预约成功。'}</p>${button(state.qualified?'查看服务方案':'预约免费体验',state.qualified?'view-package':'free-experience','primary full')}</div>`}</div>`;}
function offeringPage(){const f=offers[offerId];return `<div class="stack"><div class="card"><div class="program-mini">${icon('leaf')}</div><h2 style="margin:14px 0 7px">${f.name}</h2><p class="muted">${f.subtitle}</p><div class="divider"></div><span class="amount">${money(f.price)}</span><small> / ${f.label}</small></div><div class="card"><h3>包含内容</h3><div class="list-item"><div class="row between"><span>${offerId==='assessment'?'初次服务评估':'机构确认的服务项目'}</span><strong>${f.count} 次</strong></div><p class="muted">每次成交分摊 ${money(f.unit)}</p></div>${f.goods?`<div class="list-item"><div class="row between"><span>配套护理用品</span><strong>1 份</strong></div><p class="muted">成交分摊 ${money(f.goods)} · 机构领取</p></div>`:''}</div><div class="card"><h3>购买前请了解</h3><dl><div><dt>服务机构</dt><dd>心悦服务中心</dd></div><div><dt>有效期</dt><dd>付款后 90 天</dd></div><div><dt>近期可约</dt><dd>${state.scenario==='unavailable'?'暂未开放':`${dates()[0].short} 起`}</dd></div><div><dt>取消与退款</dt><dd>未使用按分摊金额退</dd></div><div><dt>适用确认</dt><dd>${offerId==='assessment'?'可直接购买':state.qualified?'已确认，可购买':'需要机构评估'}</dd></div></dl></div>${note(state.scenario==='unavailable'?'机构尚未开放时段，暂停新购买。您可以先咨询。':'日期仅供参考，实际预约需机构确认。因机构原因无法安排可顺延或申请退款。')}</div>`;}
function checkoutPage(){const f=offers[offerId];return `<form id="checkout-form" data-form="pay" class="stack"><div class="card"><h3>确认您购买的内容</h3><p class="muted" style="margin:7px 0">${f.name} · 心悦服务中心</p><div class="divider"></div><dl><div><dt>${f.count} 次${offerId==='assessment'?'评估':'服务'}</dt><dd>${money(f.count*f.unit)}</dd></div>${f.goods?`<div><dt>配套护理用品 × 1</dt><dd>${money(f.goods)}</dd></div>`:''}<div><dt>应付合计</dt><dd><strong class="amount">${money(f.price)}</strong></dd></div></dl></div><div class="card"><dl><div><dt>服务使用人</dt><dd>体验用户（本人）</dd></div><div><dt>来源主理人</dt><dd>林主理人 · 本服务产品</dd></div><div><dt>服务有效期</dt><dd>支付日起 90 天</dd></div></dl></div><label class="check"><input type="checkbox" name="agreement" required>已阅读并同意购买规则：本人使用；付款后预约；未使用内容按购买分摊价格退；具体安排由机构确认。</label>${note('点击下方按钮模拟支付成功。不会调用微信支付或产生扣款。','warning')}</form>`;}
function successPage(){return `<div class="stack"><div class="center" style="padding:20px 0"><div class="success-icon">${icon('check')}</div><h2>购买成功</h2><p class="muted">您可以开始安排第一次服务了</p></div><div class="card">${orderSummary()}<div class="divider"></div><dl><div><dt>已付金额</dt><dd>${money(offer().price)}</dd></div><div><dt>服务次数</dt><dd>${offer().count} 次</dd></div><div><dt>订单编号</dt><dd>${esc(current()?.id)}</dd></div></dl></div>${note('购买成功后还需选择时间，并等待机构确认预约。')}${button('查看我的服务','nav','full','data-page="plan"')}</div>`;}
function servicesPage(){const list=state.orders.filter(o=>filter==='all'||group(o)===filter);return `<div class="stack"><div class="filter-tabs">${[['all','全部'],['active','进行中'],['after','售后中'],['done','已完成'],['closed','已退款/关闭']].map(([id,t])=>`<button data-action="filter" data-filter="${id}" class="${filter===id?'active':''}">${t}</button>`).join('')}</div>${list.length?list.map(o=>`<button class="card" style="text-align:left" data-action="select-order" data-id="${o.id}"><div class="row between"><small>心悦服务中心</small>${tag(({active:'进行中',after:'售后中',done:'已完成',closed:'已退款/关闭'})[group(o)],group(o)==='after'?'warn':'')}</div><div class="divider"></div>${orderSummary(o)}<p style="margin-top:15px" class="muted">剩余 ${remaining(o)} 次 · 已完成 ${o.used} 次 ${pendingRefund(o)?'· 部分售后冻结':''}</p><div class="row between" style="margin-top:12px"><small>${o.appointment?appStatus(o.appointment):'点击查看下一步'}</small>${icon('arrow')}</div></button>`).join(''):empty('这里还没有服务','选择适合的方案，开始安排您的服务。','view-product','了解服务')}</div>`;}
function nextStep(o){const r=pendingRefund(o),a=o.appointment;if(r&&available(o)===0)return {title:'退款申请正在处理',desc:'本次所选内容已冻结，其他记录仍可查看。',text:'查看售后进度',action:'nav',attrs:'data-page="refundDetail"'};if(a&&['pending','confirmed','arrived'].includes(a.status))return {title:appStatus(a),desc:`${a.date} ${a.time} · ${a.status==='confirmed'?'请按预约时间到场':'机构将继续为您安排'}`,text:'查看预约',action:'nav',attrs:'data-page="appointment"'};if(available(o)>0)return {title:'安排您的下一次服务',desc:`还有 ${available(o)} 次可预约，让服务按计划继续。`,text:'预约下一次',action:'book',attrs:''};return {title:group(o)==='closed'?'本次方案已结束':'本次服务已完成',desc:'您可以查看完整服务记录，或联系机构继续了解。',text:'查看服务记录',action:'nav',attrs:'data-page="records"'};}
function planPage(){const o=current();if(!o)return servicesPage();const next=nextStep(o),r=pendingRefund(o);return `<div class="stack"><div class="card next-card"><small>接下来</small><h2 style="margin-top:6px">${next.title}</h2><p style="margin-top:7px">${next.desc}</p>${button(next.text,next.action,'full',next.attrs)}</div><div class="card">${orderSummary()}<small style="display:block;margin-top:13px">心悦服务中心 · 付款后 90 天有效</small><div class="divider"></div><div class="grid3"><div class="metric"><strong>${available(o)}</strong><small>可预约</small></div><div class="metric"><strong>${['pending','confirmed','arrived'].includes(o.appointment?.status)?1:0}</strong><small>已预约</small></div><div class="metric"><strong>${o.used}</strong><small>已完成</small></div></div>${r?note(`售后冻结 ${r.count} 次 · ${refundStatus(r)}`,'warning'):''}</div><div class="card"><div class="section-heading"><h3>服务与交付</h3></div>${[['records','file','服务记录',`${o.records.length} 条`],...(offer().goods?[['goods','bag','配套商品',goodsRefunded(o)?'已退款':o.goodsDelivered?'已领取':'待领取']]:[]),['appointment','calendar','预约安排',appStatus(o.appointment)]].map(([p,i,t,sub])=>`<button class="list-item row between" style="width:100%" data-action="nav" data-page="${p}"><span class="row">${icon(i)}${t}</span><small>${sub} ›</small></button>`).join('')}</div><div class="card"><h3>订单与售后</h3><dl><div><dt>订单编号</dt><dd>${esc(o.id)}</dd></div><div><dt>实付金额</dt><dd>${money(offer().price)}</dd></div></dl><div class="row between">${button(latestRefund(o)?'查看退款记录':'申请退款',latestRefund(o)?'nav':'refund-entry','sm',latestRefund(o)?'data-page="refundDetail"':'')}${button('在线客服','contact','sm')}</div></div></div>`;}
function bookingPage(){if(state.scenario==='unavailable')return `<div class="stack">${empty('暂无可约时段','机构尚未开放接待安排，可先咨询。','start-consult','咨询了解')}</div>`;const o=current();const free=bookingKind==='experience';if(!free&&!o)return empty('请先选择服务','购买后可以在此安排具体时间。','view-product','查看服务');return `<div class="stack"><div class="card"><h3>${free?'初次免费体验':offer().name}</h3><p class="muted">${free?'领取后有效 30 天，每人限一次':`本次预约占用 1 次，当前可用 ${available(o)} 次`}</p></div><h3 class="section-title">选择服务日期</h3><div class="date-grid">${dates().map((d,i)=>`<button data-action="day" data-day="${i}" class="${selectedDay===i?'active':''}">${d.short}<small>${d.label}</small></button>`).join('')}</div><h3 class="section-title">选择时间</h3><div class="time-grid">${['09:30','10:30','14:00','15:00','16:00','17:00'].map(t=>`<button data-action="time" data-time="${t}" class="${selectedTime===t?'active':''}" ${t==='10:30'?'disabled':''}>${t}${t==='10:30'?' · 已满':''}</button>`).join('')}</div><div class="card"><h3>到场安排</h3><p class="muted" style="margin-top:9px">心悦服务中心 · 接待区<br>医生、护士由机构根据排班安排</p></div>${note('提交后等待机构确认。4 个工作小时内处理，最迟不晚于预约开始前 1 小时；未确认超时释放。已确认预约距开始超过 24 小时可自行取消。')}</div>`;}
function getAppointment(){return bookingKind==='experience'?state.experience:current()?.appointment;}
function appointmentPage(){const a=getAppointment();if(!a)return `<div class="stack">${empty('还没有预约安排','选择服务项目和合适的时间，机构会协助确认。',current()?'book':'free-experience','预约服务')}</div>`;return `<div class="stack"><div class="card"><div class="row between"><h3>${appStatus(a)}</h3>${tag(a.status==='pending'?'等待确认':a.status==='confirmed'?'请按时到场':'服务进度',a.status==='pending'?'warn':'')}</div><h2 style="margin:19px 0 4px">${esc(a.date)} <span style="font-size:30px">${esc(a.time)}</span></h2><p class="muted">${a.kind==='experience'?'初次免费体验':offer().name}</p><div class="divider"></div><dl><div><dt>服务机构</dt><dd>心悦服务中心</dd></div><div><dt>实际人员</dt><dd>${a.status==='pending'?'待机构安排':`${a.staff} / ${a.nurse}`}</dd></div><div><dt>预约说明</dt><dd>未完成服务不扣次</dd></div></dl></div>${a.status==='pending'?note('机构确认后，预约才正式生效。您可以随时取消待确认申请。'):note('请携带必要资料，到机构接待区报到。如安排有变化，请提前协调。')}<div class="card"><ol class="step-list"><li class="done">预约申请已提交</li><li class="${['confirmed','arrived','completed'].includes(a.status)?'done':''}">机构确认时间与人员</li><li class="${['arrived','completed'].includes(a.status)?'done':''}">患者到场</li><li class="${a.status==='completed'?'done':''}">实际完成后登记服务</li></ol></div>${['pending','confirmed'].includes(a.status)?`<div class="row">${button('取消预约','cancel-booking','full')}${a.status==='confirmed'?button('申请改约','reschedule','full'):''}</div>${a.kind!=='experience'?button('取消预约并申请退款','refund-entry','full'):''}`:''}${button('联系机构','contact','full')}</div>`;}
function recordsPage(){const o=current();return `<div class="stack">${o?.records.length?o.records.map((r,i)=>`<div class="card"><div class="row between"><h3>第 ${i+1} 次服务</h3>${tag('已完成')}</div><dl><div><dt>实际执行</dt><dd>${r.staff} / ${r.nurse}</dd></div><div><dt>登记人员</dt><dd>机构运营 · 小悦</dd></div><div><dt>登记时间</dt><dd>${esc(r.registered)}</dd></div><div><dt>扣减次数</dt><dd>1 次</dd></div></dl><button class="link" data-action="dispute" ${o.dispute?'disabled':''}>${o.dispute?'异议处理中':'记录有误？反馈异议'}</button></div>`).join(''):empty('暂时没有服务记录','完成服务后，机构将在这里登记实际执行人员与次数。','back-plan','返回我的服务')}${o?.dispute?note('异议已受理。客服将在 1 个工作日内联系，相关未结算款项暂停，其他服务仍可使用。','warning'):''}</div>`;}
function refundPage(){const o=current();if(!o)return servicesPage();if(pendingRefund(o))return refundDetailPage();const count=remaining(o);const f=offers[o.offer];return `<form id="refund-form" data-form="refund" class="stack"><div class="card">${orderSummary(o)}<div class="divider"></div><label class="field">申请退款的服务次数<select name="count" id="refund-count">${Array.from({length:count+1},(_,i)=>`<option value="${i}" ${i===count?'selected':''}>${i} 次${i===count?'（全部未使用）':''}</option>`).join('')}</select></label><small>已完成 ${o.used} 次，每次按原成交 ${money(f.unit)} 计算</small>${f.goods&&!o.goodsDelivered&&!goodsRefunded(o)?`<label class="check" style="margin-top:15px"><input type="checkbox" name="goods" id="refund-goods">同时退未领取商品 ${money(f.goods)}</label>`:''}${o.goodsDelivered?note('配套商品已领取，本次不包含。需要退货请联系售后。'):''}</div><div class="card"><div class="row between"><span>预计退款金额</span><strong class="amount" id="refund-total">${money(count*f.unit)}</strong></div></div><div class="card"><label class="field">退款原因<select name="reason"><option>调整服务安排</option><option>暂不需要后续服务</option><option>机构无法安排时间</option><option>其他原因</option></select></label></div>${o.appointment&&['pending','confirmed'].includes(o.appointment.status)?note('本次申请将一并取消当前预约。所选次数进入售后冻结，退款撤回后需要重新预约。','warning'):note('所选未使用内容在审核期间冻结，其他服务继续使用。')}<label class="check"><input type="checkbox" required name="agreement">确认申请内容、金额及冻结说明</label></form>`;}
function refundDetailPage(){const o=current(),r=latestRefund(o);if(!r)return `<div class="stack">${empty('暂无退款记录','未使用内容可以按购买时的分摊金额申请退款。','refund-entry','申请退款')}</div>`;return `<div class="stack"><div class="card"><div class="row between"><h3>${refundStatus(r)}</h3>${tag(r.status==='success'?'渠道已确认':'售后进度',r.status==='success'?'':'warn')}</div><div class="amount" style="margin:22px 0">${money(r.amount)}</div><p class="muted">${r.count} 次未使用服务${r.goods?' + 未领取商品':''}</p></div><div class="card"><h3>处理进度</h3><div class="divider"></div><ol class="step-list"><li class="done">申请已提交<small>${esc(r.createdAt)}</small></li><li class="${['processing','success','failed'].includes(r.status)?'done':''}">平台审核<small>${r.status==='rejected'?'申请未通过，未使用资格已恢复':r.status==='withdrawn'?'申请已撤回，原预约不会自动恢复':'核对未使用内容与金额'}</small></li><li class="${r.status==='success'?'done':''}">原路退款<small>${r.status==='success'?'支付渠道已确认成功，请核对原支付账户':r.status==='failed'?'渠道异常，客服正在核查，无需重复申请':'审核通过不代表已经到账'}</small></li></ol></div>${note('退款进度以支付渠道确认结果为准；原型中的渠道状态由演示操作模拟。')}${r.rejectReason?note('处理说明：'+esc(r.rejectReason)):''}${r.status==='pending'?button('撤回申请','withdraw-refund','full'):''}${['withdrawn','rejected','success'].includes(r.status)&&remaining(o)>0?button('申请其他未使用内容退款','refund-entry','full'):''}${button('在线客服','contact','full')}${button('返回我的服务','nav','full','data-page="plan"')}</div>`;}
function goodsPage(){const o=current();if(!o||!offer().goods)return `<div class="stack">${empty('方案不含配套商品','当前方案只有服务项目。','back-plan','返回服务计划')}</div>`;return `<div class="stack"><div class="card"><div class="program-mini">${icon('bag')}</div><h2 style="margin-top:15px">配套护理用品</h2><p class="muted">1 份 · 套餐内包含，无需再次付款</p><div class="divider"></div><dl><div><dt>分摊金额</dt><dd>${money(offer().goods)}</dd></div><div><dt>交付方式</dt><dd>机构现场领取</dd></div><div><dt>当前状态</dt><dd>${goodsRefunded(o)?'已退款':o.goodsDelivered?'已领取':'待领取'}</dd></div></dl></div>${pendingRefund(o)?.goods?note('商品正在售后冻结，暂不可领取。','warning'):!o.goodsDelivered&&!goodsRefunded(o)?button('确认已在机构领取','collect-goods','primary full'):o.goodsDelivered?button('联系商品售后','contact','full'):''}${note('请实际收到商品后再确认。原型可模拟领取；寄送、退货物流将在后续原型扩展。')}</div>`;}
function footer(){if(page==='product')return `<div class="phone-footer">${button('咨询了解','nav','','data-page="consult"')}${button('查看服务方案','view-package','primary')}</div>`;if(page==='offering')return `<div class="phone-footer"><div class="mobile-footer-total"><small>方案价格</small><strong>${money(offers[offerId].price)}</strong></div>${button(state.scenario==='unavailable'?'咨询可约安排':offerId==='assessment'||state.qualified?'确认购买':'先预约评估',state.scenario==='unavailable'?'start-consult':offerId==='assessment'||state.qualified?'checkout':'free-experience','primary')}</div>`;if(page==='checkout')return `<div class="phone-footer"><div class="mobile-footer-total"><small>合计</small><strong>${money(offers[offerId].price)}</strong></div><button class="btn primary" type="submit" form="checkout-form">模拟支付并购买</button></div>`;if(page==='success')return `<div class="phone-footer">${button('去预约','book','primary')}</div>`;if(page==='booking')return `<div class="phone-footer">${button('提交预约申请','submit-booking','primary',(!current()&&bookingKind!=='experience')?'disabled':'')}</div>`;if(page==='refund'&&current()&&!pendingRefund())return `<div class="phone-footer"><button class="btn primary" form="refund-form" type="submit">提交退款申请</button></div>`;return '';}
function operatorWorkspace(){const o=current();const allApps=[...(state.experience?[{...state.experience,owner:'experience',name:'初次免费体验'}]:[]),...state.orders.filter(x=>x.appointment).map(x=>({...x.appointment,owner:x.id,name:offers[x.offer].name}))];const pending=allApps.filter(a=>a.status==='pending').length;const scheduled=allApps.filter(a=>['confirmed','arrived'].includes(a.status)).length;const refunds=state.orders.filter(x=>pendingRefund(x)).length;return `<div class="intro"><div><div class="eyebrow">INSTITUTION WORKSPACE</div><h1>把安排做好，把服务记清。</h1><p>心悦服务中心 <span style="margin:0 7px">·</span> 机构运营 小悦 <span style="margin:0 7px">·</span> 医生护士无需登录</p></div><button class="btn" data-action="role" data-role="patient">${icon('user')}查看患者端</button></div><div class="admin-guide notice"><span class="demo-badge">交互演示</span><span>确认预约、登记完成后，患者端的时间与次数会同步变化。退款审核后仍需单独模拟渠道结果。</span></div><div class="admin-metrics">${[['待确认预约',pending,'确认时间与执行人员'],['已确认 / 已到场',scheduled,'协调接待与服务登记'],['售后处理中',refunds,'核对冻结内容与退款'],['已登记服务',state.orders.reduce((s,x)=>s+x.used,0),'实际执行与登记分别记录']].map(([t,n,h])=>`<div class="card"><small>${t}</small><strong>${n}<span style="font-size:12px;color:var(--muted);margin-left:6px">项</span></strong><small>${h}</small></div>`).join('')}</div><div class="admin-grid"><div class="card admin-work"><header><div class="row between"><h3>服务工作台</h3>${tag('全部为演示记录')}</div><div class="filter-tabs">${[['intake','咨询与评估'],['appointments','预约与执行'],['refunds','退款售后'],['ledger','收益与结算']].map(([id,t])=>`<button data-action="operator-tab" data-tab="${id}" class="${operatorTab===id?'active':''}">${t}</button>`).join('')}</div></header>${operatorTab==='intake'?intakeWork():operatorTab==='appointments'?appointmentWork(allApps):operatorTab==='refunds'?refundWork():ledgerWork()}</div><aside class="admin-side"><div class="card"><div class="row between"><h3>当前服务档案</h3>${icon('file')}</div><div class="divider"></div><div class="row"><div class="avatar">体</div><div><strong>体验用户</strong><p class="muted" style="font-size:12px">虚构患者 · 仅用于原型</p></div></div><dl><div><dt>可购买资格</dt><dd>${state.qualified?'单次 / 阶段服务':'等待评估'}</dd></div><div><dt>来源主理人</dt><dd>林主理人</dd></div><div><dt>当前服务</dt><dd>${o?offer().name:'尚未购买'}</dd></div></dl><div class="divider"></div>${button('打开患者当前页面','role','full','data-role="patient"')}</div><div class="card" style="margin-top:18px"><h3>业务操作记录</h3>${state.events.length?state.events.slice(0,6).map(e=>`<div class="history"><p>${esc(e.message)}</p><small>${esc(e.time)}</small></div>`).join(''):'<p class="muted" style="margin-top:15px">完成操作后，记录将显示在这里。</p>'}</div><div class="card" style="margin-top:18px"><h3>跳到关键场景</h3><div class="scenarios" style="margin-top:14px">${[['booked','预约待确认'],['completed','已完成三次服务'],['refund','剩余七次退款']].map(([s,t])=>`<button class="scenario" data-action="scenario" data-scene="${s}">${t}${icon('arrow')}</button>`).join('')}</div></div></aside></div>`;}
function intakeWork(){return `<div class="detail"><div class="row between"><div><h2>体验用户的服务咨询</h2><p class="muted" style="margin-top:7px">${esc(state.consultation?.message||'体验场景：先了解需求，再确认可购买的服务。')}</p></div>${tag(state.qualified?'已确认可购买':'待评估',state.qualified?'':'warn')}</div><div class="divider"></div><div class="timeline-banner"><h3>业务评估结果</h3><p class="muted" style="margin-top:10px">记录确认医生、日期与允许购买的方案。专业诊疗信息由机构保管。</p><dl><div><dt>确认医生</dt><dd>陈医生</dd></div><div><dt>允许购买</dt><dd>单次专业服务、阶段服务方案</dd></div><div><dt>资格期限</dt><dd>确认日起 30 天</dd></div></dl></div>${state.qualified?note('患者可以进入方案详情并购买。原型中展示的是业务资格，不包含诊断。'):button('登记评估：允许购买','qualify','primary')}${state.experience?`<div class="divider"></div><p>体验预约：${esc(state.experience.date)} ${esc(state.experience.time)} · ${appStatus(state.experience)}</p>${button('处理体验预约','operator-tab','sm','data-tab="appointments"')}`:''}</div>`;}
function appointmentWork(list){return `<div class="table-scroll"><table class="admin-table"><thead><tr><th>患者 / 项目</th><th>预约时间</th><th>状态</th><th>执行人员</th><th>操作</th></tr></thead><tbody>${list.length?list.map(a=>`<tr><td><strong>体验用户</strong><div class="muted" style="margin-top:6px">${a.name}</div></td><td>${esc(a.date)}<br><small>${esc(a.time)}</small></td><td>${tag(appStatus(a),a.status==='pending'?'warn':'')}</td><td>${a.status==='pending'?'待安排':`${a.staff}<br><small>${a.nurse}</small>`}</td><td><div class="table-action">${a.status==='pending'?button('确认预约','confirm-appointment','primary sm',`data-owner="${a.owner}"`):a.status==='confirmed'?button('确认到场','arrive','soft sm',`data-owner="${a.owner}"`):a.status==='arrived'?button('登记完成','complete-service','primary sm',`data-owner="${a.owner}"`):'<small>记录已保存</small>'}</div></td></tr>`).join(''):'<tr><td colspan="5" class="empty-cell">暂无预约申请<br><br>在患者端购买后提交预约，或载入“预约待确认”场景。</td></tr>'}</tbody></table></div><div class="detail">${note('先确认到场，再登记实际服务完成。预约确认不会扣减次数；真实完成后才核销。')}<div class="toolbar">${button('去患者端预约','operator-patient-book','soft')}${button('载入预约待确认场景','scenario','','data-scene="booked"')}</div></div>`;}
function refundWork(){const list=state.orders.filter(o=>o.refunds.length);return `<div class="detail">${list.length?list.map(o=>{const r=latestRefund(o);return `<div class="card" style="margin-bottom:15px"><div class="row between"><div><h3>${offers[o.offer].name}</h3><small>${esc(o.id)}</small></div>${tag(refundStatus(r),r.status==='success'?'':'warn')}</div><div class="divider"></div><dl><div><dt>申请内容</dt><dd>${r.count} 次未使用服务${r.goods?' + 未交付商品':''}</dd></div><div><dt>已完成次数</dt><dd>${o.used} 次</dd></div><div><dt>本次退款</dt><dd class="amount">${money(r.amount)}</dd></div><div><dt>原因</dt><dd>${esc(r.reason)}</dd></div></dl>${r.status==='pending'?note('批准后提交退款，所选内容继续冻结，等待渠道确认。'):r.status==='processing'?note('这里模拟渠道回调。实际系统应以微信通知或查询结果为准。','warning'):r.status==='failed'?note('异常时继续冻结，不重复发起退款。查询结果后再更新。','warning'):note('该申请已结束，历史记录保留。')}<div class="toolbar">${r.status==='pending'?button('批准退款','approve-refund','primary',`data-order="${o.id}"`)+button('拒绝申请','reject-refund','',`data-order="${o.id}"`):['processing','failed'].includes(r.status)?button('模拟渠道确认成功','refund-success','primary',`data-order="${o.id}"`)+(r.status==='processing'?button('模拟渠道异常','refund-failed','',`data-order="${o.id}"`):''):''}</div></div>`;}).join(''):empty('暂无退款申请','在患者端选择未使用次数发起退款后，可在此处理。','scenario','载入退款场景').replace('data-action="scenario"','data-action="scenario" data-scene="refund"')}</div>`;}
function ledgerWork(){const o=current();if(!o)return `<div class="detail">${empty('尚无服务收益','完成服务后才产生计提，支付成功不直接结算。','scenario','载入已完成场景').replace('data-action="scenario"','data-action="scenario" data-scene="completed"')}</div>`;const f=offer(),goods=o.goodsDelivered&&!goodsRefunded(o)?f.goods:0,commission=Math.round(o.used*f.unit*f.rate+goods*.05),institution=o.used*f.cost+(goods?7000:0),refund=o.refunds.filter(r=>r.status==='success').reduce((s,r)=>s+r.amount,0);return `<div class="detail"><div class="row between"><h2>按实际完成内容计提</h2>${tag(o.dispute?'异议冻结':'观察期内',o.dispute?'red':'warn')}</div><p class="muted" style="margin:8px 0 20px">${f.name} · 林主理人 · 来源归属固定</p><div class="ledger"><div class="row between"><span>订单实收</span><strong>${money(f.price)}</strong></div><div class="row between"><span>已成功退款</span><strong>${money(refund)}</strong></div><div class="row between"><span>完成服务金额（${o.used} 次）</span><strong>${money(o.used*f.unit)}</strong></div><div class="row between"><span>已交付商品金额</span><strong>${money(goods)}</strong></div><div class="row between total"><span>主理人预计收益</span><strong>${money(commission)}</strong></div><div class="row between"><span>机构预计结算</span><strong>${money(institution)}</strong></div></div><div class="divider"></div>${note(`服务计提比例 ${(f.rate*100).toFixed(0)}%，商品 5%；机构服务单价 ${money(f.cost)}，示例商品结算 ¥70.00。未使用部分不计提。`)}<div class="timeline-banner"><h3>结算安排</h3><p class="muted" style="margin-top:8px">记录对患者可见后累计 7 天无争议，才进入可结算；每月 5 日出单，5 个工作日内处理无争议付款。</p></div><small>本原型只展示当前示例的计提逻辑，不模拟真实转账、财务账务或完整月度结算。</small></div>`;}
function guide(){return `<div class="review-guide"><div><div class="eyebrow">REVIEW GUIDE</div><h1>先走通流程，再确认页面。</h1><p class="muted" style="margin-top:12px">原型依据已确认的需求 V1.2，聚焦患者与机构运营两个角色。</p></div><div class="card"><h2>建议体验顺序</h2><ol><li>首次咨询：提交咨询，预约免费体验。</li><li>切换机构运营：确认预约、到场和完成，登记可购买资格。</li><li>切回患者：购买阶段方案，选择时间并提交预约。</li><li>运营确认并登记完成，患者查看已完成和剩余次数。</li><li>载入“已完成三次服务”，申请退剩余七次。</li><li>运营批准后切回患者查看“渠道处理中”，再模拟渠道成功。</li></ol>${button('从首次咨询开始','scenario','primary','data-scene="start"')}</div><div class="card"><h2>本轮可以评审什么</h2><p style="margin-top:10px">页面层级、主要按钮、角色切换、可用与冻结次数、审核与退款结果的区别、实际执行与登记人员的区别。</p></div><div class="card"><h2>演示范围</h2><p style="margin-top:10px">使用一个虚构患者和机构。浏览器保存演示进度，可随时重置。支付、渠道回调、人员资料均为模拟；不连接线上系统，也不发送消息。</p><p style="margin-top:10px">套餐物流退货、方案替换购买、多机构管理、真实主理人工作台和完整财务结算属于后续原型范围。原型中客服与改约弹窗提供流程说明，不代表相关功能已经实现。</p></div><div class="card"><h2>空白、加载与错误状态</h2><p style="margin-top:10px">首次进入“我的服务”可查看空白状态。患者端右侧可切换加载中、加载失败，再点击重试恢复。手机窄屏中评审工具显示在页面下方。</p></div></div>`;}
function render(){
  if(current()===undefined&&['plan','success','refund','refundDetail','records','goods'].includes(page))page='services';
  $('#app').innerHTML=shell();
}
function contextAppointment(owner){return owner==='experience'?state.experience:state.orders.find(o=>o.id===owner)?.appointment;}
const actions={
  nav:b=>{if(b.dataset.page==='appointment'&&current())bookingKind='service';go(b.dataset.page);},
  'patient-page':b=>{role='patient';go(b.dataset.page);},
  role:b=>{const next=b.dataset.role;if(role==='patient'&&next==='operator'){operatorTab=['refund','refundDetail'].includes(page)?'refunds':['booking','appointment'].includes(page)?'appointments':page==='consultation'?'intake':operatorTab;}role=next;render();},
  'operator-tab':b=>{operatorTab=b.dataset.tab;render();},
  scenario:b=>{if(role==='guide')role='patient';seed(b.dataset.scene);},
  reset:()=>dialog('重置演示记录？','<p>会清除本浏览器的原型订单与操作记录，恢复首次咨询场景。</p>',button('保留进度','close-dialog')+button('重置演示','confirm-reset','primary')),
  'confirm-reset':()=>{closeDialog();seed('start');},
  'close-dialog':closeDialog,
  back:()=>{const map={offering:'product',checkout:'offering',success:'plan',plan:'services',booking:bookingKind==='experience'?'consultation':'plan',appointment:bookingKind==='experience'?'consultation':'plan',records:'plan',refund:'plan',refundDetail:'plan',goods:'plan',consult:'product'};go(map[page]||'product');},
  offer:b=>{offerId=b.dataset.offer;go('offering');},
  'view-package':()=>{offerId='package';go('offering');},
  'view-product':()=>go('product'),
  'start-consult':()=>go('consult'),
  checkout:()=>{if(state.scenario==='unavailable'){toast('机构暂未开放预约，暂停购买');return;}if(offerId!=='assessment'&&!state.qualified){toast('请先由机构完成适用性确认');return;}go('checkout');},
  retry:()=>{uiState='normal';render();toast('已恢复演示页面');},
  filter:b=>{filter=b.dataset.filter;render();},
  'select-order':b=>{state.activeId=b.dataset.id;bookingKind='service';save();go('plan');},
  'back-plan':()=>go('plan'),
  'free-experience':()=>{bookingKind='experience';if(state.experience&&state.experience.status!=='cancelled'){go('appointment');return;}go('booking');},
  book:()=>{bookingKind='service';if(!current()){go('product');return;}if(available()<=0){toast('当前没有可预约次数');return;}go('booking');},
  day:b=>{selectedDay=Number(b.dataset.day);render();},
  time:b=>{selectedTime=b.dataset.time;render();},
  'submit-booking':()=>{if(state.scenario==='unavailable'){toast('暂无可约时段，请先咨询');return;}if(bookingKind==='experience'){if(state.experience&&state.experience.status!=='cancelled'){toast('已有体验安排');return;}state.experience=appointment('experience');}else{if(!current()||available()<=0){toast('暂无可用次数');return;}current().appointment=appointment();}log('患者提交预约申请，等待机构确认');go('appointment');toast('申请已提交，等待机构确认');},
  'cancel-booking':()=>dialog('取消这次预约？','<p>原时段将释放，未使用的服务次数恢复可预约。</p>',button('暂不取消','close-dialog')+button('确认取消','confirm-cancel','primary')),
  'confirm-cancel':()=>{const a=getAppointment();if(a&&['pending','confirmed'].includes(a.status)){a.status='cancelled';log('患者取消预约，释放占用');}closeDialog();render();},
  reschedule:()=>dialog('重新安排服务时间','<p>您可以取消当前预约，再选择新的时间。距开始不足 24 小时的改约由客服协调。</p><p class="muted" style="margin-top:10px">当前演示预约在两天后，可以自行取消。</p>',button('保留预约','close-dialog')+button('取消并重选时间','cancel-rebook','primary')),
  'cancel-rebook':()=>{const a=getAppointment();if(a)a.status='cancelled';log('患者取消原预约并重新选择时间');closeDialog();go('booking');},
  qualify:()=>dialog('登记机构确认结果','<p>确认医生：陈医生<br>指定方案：单次专业服务、阶段服务方案<br>有效期：确认日起 30 天</p><div style="margin-top:12px">'+note('演示仅记录业务资格，不记录诊断。')+'</div>',button('取消','close-dialog')+button('确认登记','confirm-qualify','primary')),
  'confirm-qualify':()=>{state.qualified=true;log('机构登记陈医生确认的可购买资格');closeDialog();render();toast('患者可购买相应服务方案');},
  'confirm-appointment':b=>dialog('确认预约与执行人员',`<form id="staff-form" data-form="staff" class="stack"><input type="hidden" name="owner" value="${esc(b.dataset.owner)}"><label class="field">医生<select name="staff"><option>陈医生</option><option>周医生</option></select></label><label class="field">护士<select name="nurse"><option>李护士</option><option>王护士</option></select></label>${note('确认后患者可以查看时间、地点和安排的人员。')}</form>`,button('取消','close-dialog')+'<button class="btn primary" type="submit" form="staff-form">确认预约</button>'),
  arrive:b=>{const a=contextAppointment(b.dataset.owner);if(a?.status!=='confirmed')return;a.status='arrived';log('机构确认患者到场');render();},
  'complete-service':b=>dialog('登记实际服务完成',`<form id="complete-form" data-form="complete" class="stack"><input type="hidden" name="owner" value="${esc(b.dataset.owner)}"><p>登记人员：机构运营 小悦<br>实际执行：${esc(contextAppointment(b.dataset.owner)?.staff)} / ${esc(contextAppointment(b.dataset.owner)?.nurse)}</p><label class="field">完成依据<textarea name="evidence" required maxlength="200" placeholder="填写实际完成内容及核对依据">已与执行人员核对，本次服务已实际完成。</textarea></label><label class="check"><input type="checkbox" required>确认已实际完成，登记后扣减一次服务</label></form>`,button('取消','close-dialog')+'<button class="btn primary" type="submit" form="complete-form">确认完成并登记</button>'),
  'operator-patient-book':()=>{role='patient';if(current()){bookingKind='service';go(available()>0?'booking':'plan');}else go('product');},
  'refund-entry':()=>{if(!current()){go('services');return;}if(current().appointment?.status==='arrived'){toast('服务执行中，请通过客服受理异议');return;}if(pendingRefund()){go('refundDetail');return;}if(remaining()===0&&(!offer().goods||current().goodsDelivered||goodsRefunded(current()))){toast('没有可直接退款内容，请联系售后');return;}go('refund');},
  'withdraw-refund':()=>{const r=latestRefund();if(r?.status!=='pending')return;r.status='withdrawn';log('患者撤回退款，解除冻结；原预约不恢复');render();toast('申请已撤回，需要重新预约');},
  'approve-refund':b=>dialog('批准本次退款？',note('批准后显示“渠道处理中”，所选服务保持冻结。渠道确认成功后才终结已退次数。'),button('取消','close-dialog')+button('批准并提交渠道','confirm-approve','primary',`data-order="${b.dataset.order}"`)),
  'confirm-approve':b=>{const o=state.orders.find(o=>o.id===b.dataset.order),r=latestRefund(o);if(r?.status!=='pending')return;r.status='processing';log('平台批准退款，等待渠道确认');closeDialog();render();},
  'reject-refund':b=>dialog('拒绝退款申请',`<form id="reject-form" data-form="reject" class="stack"><input name="order" type="hidden" value="${esc(b.dataset.order)}"><label class="field">处理说明<textarea name="reason" required maxlength="200" placeholder="向患者说明处理原因"></textarea></label></form>`,button('返回','close-dialog')+'<button class="btn danger" type="submit" form="reject-form">确认拒绝</button>'),
  'refund-success':b=>{const o=state.orders.find(o=>o.id===b.dataset.order),r=latestRefund(o);if(!['processing','failed'].includes(r?.status))return;r.status='success';log(`模拟渠道确认退款成功 ${money(r.amount)}`);render();},
  'refund-failed':b=>{const r=latestRefund(state.orders.find(o=>o.id===b.dataset.order));if(r?.status!=='processing')return;r.status='failed';log('模拟退款渠道异常，保持冻结等待核查');render();},
  'collect-goods':()=>dialog('确认收到配套商品？','<p>本次领取配套护理用品 1 份，属于套餐已支付内容，无需再次付款。</p>',button('尚未收到','close-dialog')+button('已收到，确认领取','confirm-collect','primary')),
  'confirm-collect':()=>{const o=current();if(!o||o.goodsDelivered||goodsRefunded(o)||pendingRefund(o)?.goods)return;o.goodsDelivered=true;log('患者确认领取套餐商品');closeDialog();render();},
  dispute:()=>dialog('反馈服务记录问题','<form id="dispute-form" data-form="dispute" class="stack"><label class="field">问题类型<select name="type"><option>次数不符</option><option>未接受该服务</option><option>项目不符</option></select></label><label class="field">补充说明<textarea name="message" required maxlength="200" placeholder="请描述需要核查的内容"></textarea></label></form>',button('取消','close-dialog')+'<button class="btn primary" type="submit" form="dispute-form">提交异议</button>'),
  contact:()=>dialog('联系机构客服',`<p>您可以携带当前服务与订单信息咨询。</p><div class="divider"></div><dl><div><dt>机构</dt><dd>心悦服务中心</dd></div><div><dt>当前订单</dt><dd>${esc(current()?.id||'暂无')}</dd></div></dl>${note('这是客服入口的交互示意。原型不会打开真实微信会话或发送消息。')}`,button('知道了','close-dialog','primary')),
};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const fn=actions[b.dataset.action];if(fn)fn(b);});
document.addEventListener('change',e=>{if(e.target.dataset.control==='view-state'){uiState=e.target.value;render();}if(e.target.id==='refund-count'||e.target.id==='refund-goods'){const form=$('#refund-form');const data=new FormData(form);$('#refund-total').textContent=money(Number(data.get('count'))*offer().unit+(data.get('goods')?offer().goods:0));}});
document.addEventListener('submit',e=>{
 const form=e.target;if(!form.dataset.form)return;e.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);
 switch(form.dataset.form){
 case 'consult':state.consultation={name:String(data.get('name')),message:String(data.get('message'))};log('患者提交服务咨询');go('consultation');toast('咨询已提交');break;
 case 'pay':if(offerId!=='assessment'&&!state.qualified){toast('当前尚未获得购买资格');return;}makeOrder();bookingKind='service';log(`患者模拟购买${offers[offerId].name} ${money(offers[offerId].price)}`);go('success');break;
 case 'staff':{const a=contextAppointment(data.get('owner'));if(a?.status!=='pending')return;a.staff=String(data.get('staff'));a.nurse=String(data.get('nurse'));a.status='confirmed';log('机构确认预约并分配执行人员');closeDialog();render();break;}
 case 'complete':{const owner=data.get('owner'),a=contextAppointment(owner);if(a?.status!=='arrived')return;a.status='completed';if(owner!=='experience'){const o=state.orders.find(o=>o.id===owner);if(remaining(o)<=0)return;o.used++;o.records.push({id:o.used,date:`${a.date} ${a.time}`,staff:a.staff,nurse:a.nurse,registered:time(),evidence:String(data.get('evidence'))});if(o.offer==='assessment')toast('评估服务已登记，可在咨询与评估页确认购买资格');}log('运营登记实际服务完成，执行人与登记人分别记录');closeDialog();render();break;}
 case 'refund':{const o=current();if(!o||pendingRefund(o))return;const count=Number(data.get('count')),goods=!!data.get('goods');if(!Number.isInteger(count)||count<0||count>remaining(o)||count===0&&!goods){toast('请至少选择一项未使用内容');return;}if(o.appointment?.status==='arrived'){toast('执行中的服务请联系售后处理');return;}if(o.appointment&&['pending','confirmed'].includes(o.appointment.status)&&count>0)o.appointment.status='cancelled';o.refunds.push({count,goods,amount:count*offer().unit+(goods?offer().goods:0),reason:String(data.get('reason')),status:'pending',createdAt:time()});log('患者提交退款，冻结所选内容并取消关联预约');go('refundDetail');break;}
 case 'reject':{const o=state.orders.find(o=>o.id===data.get('order')),r=latestRefund(o);if(r?.status!=='pending')return;r.status='rejected';r.rejectReason=String(data.get('reason'));log('平台拒绝申请并记录原因，解除未使用内容冻结');closeDialog();render();break;}
 case 'dispute':{if(!current())return;current().dispute={type:String(data.get('type')),message:String(data.get('message'))};log('患者反馈服务记录异议，相关未结算款项暂停');closeDialog();render();break;}
 }
});
render();
